package academy.tochkavhoda.competition.service;

import academy.tochkavhoda.competition.database.Database;
import academy.tochkavhoda.competition.model.*;
import academy.tochkavhoda.competition.server.ServerResponse;
import academy.tochkavhoda.competition.util.Json;
import java.util.*;

public final class CompetitionService {
 private final Database db; private final AccountService accounts;
 public CompetitionService(){this(Database.getInstance(),new AccountService());}
 public CompetitionService(Database db,AccountService accounts){this.db=db;this.accounts=accounts;}
 public ServerResponse addApplication(String token,String json){return run(()->{Account a=accounts.authorized(token);if(!(a instanceof Participant))throw new IllegalArgumentException("Операция доступна только участнику");Map<String,Object> m=Json.object(json);String title=str(m,"title"),description=str(m,"description");Object raw=m.get("directions");if(!(raw instanceof List)||((List<?>)raw).isEmpty())throw new IllegalArgumentException("Необходимо указать направления заявки");Set<String> dirs=new LinkedHashSet<>();for(Object d:(List<?>)raw){if(!(d instanceof String)||((String)d).trim().isEmpty())throw new IllegalArgumentException("Направление не должно быть пустым");dirs.add(((String)d).trim());}Object amount=m.get("requestedAmount");if(!(amount instanceof Number)||!Double.isFinite(((Number)amount).doubleValue())||((Number)amount).doubleValue()<=0)throw new IllegalArgumentException("Запрашиваемая сумма должна быть положительным числом");String id=UUID.randomUUID().toString();db.addApplication(new GrantApplication(id,a.getId(),title,description,dirs,((Number)amount).doubleValue()));return Json.stringify(Map.of("applicationId",id));});}
 public ServerResponse cancelApplication(String token,String json){return run(()->{Account a=accounts.authorized(token);if(!(a instanceof Participant))throw new IllegalArgumentException("Операция доступна только участнику");String id=str(Json.object(json),"applicationId");GrantApplication app=db.application(id);if(app==null||!app.getParticipantId().equals(a.getId()))throw new IllegalArgumentException("Заявка не найдена у данного участника");db.removeApplication(id);return "{}";});}
 public ServerResponse rateApplication(String token,String json){return run(()->{Account a=accounts.authorized(token);if(!(a instanceof Expert))throw new IllegalArgumentException("Операция доступна только эксперту");Expert e=(Expert)a;Map<String,Object> m=Json.object(json);String id=str(m,"applicationId");GrantApplication app=db.application(id);if(app==null)throw new IllegalArgumentException("Заявка не найдена");boolean matches=app.getDirections().stream().anyMatch(e.getDirections()::contains);if(!matches)throw new IllegalArgumentException("Эксперт не специализируется на направлениях этой заявки");Object raw=m.get("score");if(!(raw instanceof Number)||((Number)raw).doubleValue()%1!=0||((Number)raw).intValue()<1||((Number)raw).intValue()>5)throw new IllegalArgumentException("Оценка должна быть целым числом от 1 до 5");db.putRating(new Rating(id,e.getId(),((Number)raw).intValue()));return "{}";});}
 public ServerResponse deleteRating(String token,String json){return run(()->{Account a=accounts.authorized(token);if(!(a instanceof Expert))throw new IllegalArgumentException("Операция доступна только эксперту");String id=str(Json.object(json),"applicationId");if(db.application(id)==null||!db.removeRating(id,a.getId()))throw new IllegalArgumentException("Оценка не найдена");return "{}";});}
 public ServerResponse getApplications(String token,String json){return run(()->{Account a=accounts.authorized(token);if(!(a instanceof Expert))throw new IllegalArgumentException("Операция доступна только эксперту");Expert e=(Expert)a;Set<String> filter=new HashSet<>();if(json!=null&&!json.isBlank()){Object raw=Json.object(json).get("directions");if(raw!=null){if(!(raw instanceof List))throw new IllegalArgumentException("directions должен быть массивом");for(Object x:(List<?>)raw){if(!(x instanceof String))throw new IllegalArgumentException("Некорректное направление");filter.add((String)x);}if(!e.getDirections().containsAll(filter))throw new IllegalArgumentException("Запрошено направление вне специализации эксперта");}}List<Object> out=new ArrayList<>();for(GrantApplication app:db.applications()){boolean direction=filter.isEmpty()?app.getDirections().stream().anyMatch(e.getDirections()::contains):app.getDirections().stream().anyMatch(filter::contains);if(direction)out.add(applicationJson(app));}return Json.stringify(Map.of("applications",out));});}
 public ServerResponse getRatedApplications(String token){return run(()->{Account a=accounts.authorized(token);if(!(a instanceof Expert))throw new IllegalArgumentException("Операция доступна только эксперту");List<Object> out=new ArrayList<>();for(Rating r:db.ratingsByExpert(a.getId())){GrantApplication app=db.application(r.getApplicationId());if(app!=null){Map<String,Object> item=applicationJson(app);item.put("score",r.getScore());out.add(item);}}return Json.stringify(Map.of("applications",out));});}
 public ServerResponse results(String token,String json){return run(()->{accounts.authorized(token);Map<String,Object> m=Json.object(json);double fund=number(m,"fund");double minScore=number(m,"minAverageScore");if(fund<0||minScore<1||minScore>5)throw new IllegalArgumentException("Фонд должен быть неотрицательным, порог — от 1 до 5");Map<String,List<Rating>> byApp=new HashMap<>();for(Rating r:db.ratings())byApp.computeIfAbsent(r.getApplicationId(),k->new ArrayList<>()).add(r);List<Map<String,Object>> rows=new ArrayList<>();for(GrantApplication app:db.applications()){List<Rating> rs=byApp.getOrDefault(app.getId(),List.of());if(rs.isEmpty())continue;double avg=rs.stream().mapToInt(Rating::getScore).average().orElse(0);Map<String,Object> row=applicationJson(app);row.put("averageScore",avg);row.put("ratingCount",rs.size());rows.add(row);}rows.sort((x,y)->{int c=Double.compare((Double)y.get("averageScore"),(Double)x.get("averageScore"));if(c!=0)return c;c=Double.compare((Double)x.get("requestedAmount"),(Double)y.get("requestedAmount"));return c!=0?c:String.valueOf(x.get("applicationId")).compareTo(String.valueOf(y.get("applicationId")));});Random random=new Random();for(int start=0;start<rows.size();){int end=start+1;while(end<rows.size()&&Double.compare((Double)rows.get(start).get("averageScore"),(Double)rows.get(end).get("averageScore"))==0&&Double.compare((Double)rows.get(start).get("requestedAmount"),(Double)rows.get(end).get("requestedAmount"))==0)end++;Collections.shuffle(rows.subList(start,end),random);start=end;}double remaining=fund;List<Object> winners=new ArrayList<>();for(Map<String,Object> row:rows){double avg=(Double)row.get("averageScore");if(avg<=minScore)break;double amount=(Double)row.get("requestedAmount");row.put("funded",amount<=remaining);if(amount<=remaining){remaining-=amount;row.put("allocatedAmount",amount);winners.add(row);}else row.put("allocatedAmount",0.0);}return Json.stringify(Map.of("rankedApplications",rows,"fundedApplications",winners,"remainingFund",remaining));});}
 private static Map<String,Object> applicationJson(GrantApplication a){Map<String,Object> m=new LinkedHashMap<>();m.put("applicationId",a.getId());m.put("title",a.getTitle());m.put("description",a.getDescription());m.put("directions",a.getDirections());m.put("requestedAmount",a.getRequestedAmount());return m;}
 private static String str(Map<String,Object> m,String k){Object v=m.get(k);if(!(v instanceof String)||((String)v).trim().isEmpty())throw new IllegalArgumentException("Поле '"+k+"' обязательно");return ((String)v).trim();}
 private static double number(Map<String,Object> m,String k){Object v=m.get(k);if(!(v instanceof Number)||!Double.isFinite(((Number)v).doubleValue()))throw new IllegalArgumentException("Поле '"+k+"' должно быть числом");return ((Number)v).doubleValue();}
 private ServerResponse run(Work w){try{return new ServerResponse(200,w.run());}catch(RuntimeException e){return new ServerResponse(400,Json.stringify(Map.of("error",e.getMessage()==null?"Ошибка запроса":e.getMessage())));}}
 @FunctionalInterface private interface Work{String run();}
}
